import java.util.Scanner;

public class Main {
    static final int MAXN = (1 << 19) | 5;
    static int n, k, p, maxn;
    static int[] count_bits = new int[MAXN];
    static int[] f_vals = new int[MAXN];
    static long total_pow;
    static long[][] trans = new long[20][MAXN];
    static long[][] fact_arr = new long[MAXN];
    static long[] inv_fact_arr = new long[MAXN];
    static int[][] tmp1_tmp = new int[20][MAXN];
    static int[][] tmp2_tmp = new int[20][MAXN];
    static int[][] tmp3_tmp = new int[20][MAXN];

    static long power(long base, long exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * cur % p;
            cur = cur * cur % p;
            exp >>= 1;
        }
        return res;
    }

    static void setup() {
        fact_arr[0] = 1;
        for (int i = 1; i <= maxn; i++)
            fact_arr[i] = fact_arr[i - 1] * i % p;
        inv_fact_arr[maxn] = power(fact_arr[maxn], p - 2);
        for (int i = maxn - 1; i >= 0; i--)
            inv_fact_arr[i] = inv_fact_arr[i + 1] * (i + 1) % p;
    }

    static int get_lower_power(int x) {
        int res = 1;
        while (res < x) res <<= 1;
        return res;
    }

    static void FWT(int[] arr, int len, boolean inv) {
        long[] temp = new long[len];
        for (int i = 0; i < len; i++) temp[i] = arr[i];
        for (int step = 1; step < len; step <<= 1) {
            for (int j = 0; j < len; j += (step << 1)) {
                for (int k = j; k < j + step; k++) {
                    long val = temp[k];
                    if (inv) {
                        temp[k + step] -= val;
                    } else {
                        temp[k + step] += val;
                    }
                }
            }
        }
        for (int i = 0; i < len; i++) {
            arr[i] = (int)((temp[i] % p + p) % p);
        }
    }

    static void mod_adjust(long[] x) {
        for (int i = 0; i < x.length; i++) {
            if (x[i] >= total_pow) x[i] -= total_pow;
        }
    }

    static void do_multiply() {
        for (int i = 0; i <= maxn; i++) {
            for (int q = 0; q < 20; q++) {
                tmp1_tmp[q][i] = 0;
            }
        }
        for (int q = 0; q < 20; q++) {
            for (int i = 0; i <= maxn; i++) {
                tmp1_tmp[q][i] = 0;
            }
        }
        for (int i = 0; i <= maxn; i++) {
            int bits = count_bits[i];
            tmp1_tmp[bits][i] = f_vals[i];
        }
        for (int q = 0; q < 20; q++) {
            FWT(tmp1_tmp[q], maxn + 1, false);
        }
        for (int q = 0; q < 20; q++) {
            for (int l = 0; l + q < 20; l++) {
                for (int s = 0; s <= maxn; s++) {
                    long val = 1L * tmp1_tmp[q][s] * tmp2_tmp[l][s];
                    trans[q + l][s] += val;
                }
            }
        }
        for (int q = 0; q < 20; q++) {
            for (int s = 0; s <= maxn; s++) {
                trans[q][s] %= p;
            }
        }
        for (int q = 0; q < 20; q++) {
            for (int s = 0; s <= maxn; s++) {
                tmp3_tmp[q][s] = (int) trans[q][s];
            }
        }
        for (int q = 0; q < 20; q++) {
            FWT(tmp3_tmp[q], maxn + 1, true);
        }
        for (int j = 0; j <= maxn; j++) {
            int bits = count_bits[j];
            f_vals[j] = tmp3_tmp[bits][j];
        }
    }

    static void do_alt_multiply() {
        for (int i = 0; i < 20; i++) {
            for (int s = 0; s <= maxn; s++) {
                trans[i][s] = 0;
            }
        }
        for (int q = 0; q < 20; q++) {
            for (int l = 0; l + q < 20; l++) {
                for (int s = 0; s <= maxn; s++) {
                    long val = 1L * tmp2_tmp[q][s] * tmp2_tmp[l][s];
                    trans[q + l][s] += val;
                }
            }
        }
        for (int q = 0; q < 20; q++) {
            for (int s = 0; s <= maxn; s++) {
                trans[q][s] %= p;
            }
        }
        int[][] temp = new int[20][MAXN];
        for (int i = 0; i < 20; i++) {
            for (int s = 0; s <= maxn; s++) {
                temp[i][s] = (int) trans[i][s];
            }
        }
        for (int i = 0; i < 20; i++) {
            FWT(temp[i], maxn + 1, false);
        }
        for (int i = 0; i < 20; i++) {
            for (int s = 0; s <= maxn; s++) {
                tmp2_tmp[i][s] = 0;
            }
        }
        for (int i = 0; i <= maxn; i++) {
            int bits = count_bits[i];
            tmp2_tmp[bits][i] = temp[bits][i];
        }
        for (int i = 0; i < 20; i++) {
            FWT(tmp2_tmp[i], maxn + 1, true);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();
        total_pow = (long) p * p;
        if ((n & 1) == 1) {
            System.out.println(power(k, n));
            sc.close();
            return;
        }
        f_vals[0] = 1;
        maxn = get_lower_power(n + 1) - 1;
        setup();
        for (int i = 0; i <= maxn; i++) {
            count_bits[i] = Integer.bitCount(i);
        }
        for (int i = 0; i <= maxn; i++) {
            int bits = count_bits[i];
            tmp2_tmp[bits][i] = (int) inv_fact_arr[i];
        }
        for (int i = 0; i < 20; i++) {
            FWT(tmp2_tmp[i], maxn + 1, false);
        }
        int res_k = k;
        while (res_k > 0) {
            if ((res_k & 1) == 1) do_multiply();
            res_k >>= 1;
            if (res_k > 0) do_alt_multiply();
        }
        long result = (power(k, n) - fact_arr[n] * f_vals[n] % p + p) % p;
        System.out.println(result);
        sc.close();
    }
}
